/// <summary>
/// MarkupAutoSetup Form extensions MPJ_24248 Pricing Data Extract
/// </summary>
[ExtensionOf(formStr(MarkupAutoSetup))]
final class METMarkupAutoSetupForm_Extension
{
    public FormRunViewEditModeHelper    metViewEditModeHelper;
    public METMarkupAutoSetupHelper     metMarkupAutoSetupHelper;

}

Method.Source:
    /// <summary>
    /// COC on Form init
    /// </summary>
    public void init()
    {
        metViewEditModeHelper = this.viewEditModeHelper();
        
        next init();

        metMarkupAutoSetupHelper = METMarkupAutoSetupHelper::newFromFormRun(this);

        if (this.metIsGupCustMarkupAutoSetup())
        {
            metViewEditModeHelper.setViewEditMode(ViewEditMode::View);

            //Adding Handler method directly from this class gave compile error. Added to seperate class as work around, which then calls back to metEditModeSwitched()
            metViewEditModeHelper.EditModeSwitched += eventhandler(metMarkupAutoSetupHelper.editModeSwitched);
        }
    }

/// <summary>
/// is this a MarkupTable record
/// </summary>
/// <returns>true false if this is a MarkupTable record</returns>
public boolean metIsGupCustMarkupAutoSetup()
{
    return (this.args().parmEnum() == MarkupModuleType::Cust &&
            this.args().menuItemName() == menuItemDisplayStr(GUPMarkupAutoSetup_Cust));
}

/// <summary>
/// The Form has changed to Edit mode = yes
/// </summary>
public void metEditModeSwitched()
{
    this.metUpdateControls(true);
    MarkupAutoTable.metEdit();
}

    /// <summary>
    /// Enable or Disable the controls
    /// </summary>
    /// <param name = "_enabled">Enabled</param>
    public void metUpdateControls(boolean _enabled)
    {
        FormButtonGroupControl      metNewDeleteGroup1Control, metPriceAttributeGroupControl;
        FormFunctionButtonControl   metEditLinePriceAttributeButton;

        metNewDeleteGroup1Control = this.design(0).controlName(formControlStr(MarkupAutoSetup, NewDeleteGroup1));
        metNewDeleteGroup1Control.enabled(_enabled);

        metPriceAttributeGroupControl = this.design(0).controlName(formControlStr(MarkupAutoSetup, PriceAttributeGroup));
        metPriceAttributeGroupControl.enabled(_enabled);

        metEditLinePriceAttributeButton = this.design(0).controlName(formControlStr(MarkupAutoSetup, EditLinePriceAttributeButton));
        metEditLinePriceAttributeButton.enabled(_enabled);
    }

/// <summary>
/// Artificial change to the Header triggered by a Line change so the Header record is updated by Form
/// </summary>
public void metUpdateFromLine()
{
    if(MarkUpAutoTable.metIsGUPAutoCharge())
    {
        MarkupAutoTable.metLineUpdated = MarkupAutoTable.metLineUpdated + 1;
    }
}
